package main
import("context";"errors";"os";"path/filepath";"testing";"github.com/sonroyaalmerol/go-smb-server/smb/vfs")
func TestBackendReadWrite(t *testing.T){b,e:=newLocalBackend(t.TempDir(),true,true,true,false);if e!=nil{t.Fatal(e)};h,e:=b.Open(context.Background(),vfs.OpenOptions{Path:"hello.txt",Disposition:vfs.DispositionCreate});if e!=nil{t.Fatal(e)};if n,x:=h.Write(context.Background(),0,[]byte("hello"));x!=nil||n!=5{t.Fatalf("write %d %v",n,x)};_ = h.Close(context.Background());h,e=b.Open(context.Background(),vfs.OpenOptions{Path:"hello.txt",Disposition:vfs.DispositionOpen});if e!=nil{t.Fatal(e)};buf:=make([]byte,5);n,e:=h.Read(context.Background(),0,buf);if e!=nil||n!=5||string(buf)!="hello"{t.Fatalf("read %d %q %v",n,buf,e)};_ = h.Close(context.Background())}
func TestReadOnlyRejectsMutation(t *testing.T){b,e:=newLocalBackend(t.TempDir(),false,false,false,false);if e!=nil{t.Fatal(e)};_,e=b.Open(context.Background(),vfs.OpenOptions{Path:"new",Disposition:vfs.DispositionCreate});if !errors.Is(e,os.ErrPermission){t.Fatalf("want denied, got %v",e)};if e=b.Mkdir(context.Background(),"newdir");!errors.Is(e,os.ErrPermission){t.Fatalf("want mkdir denied, got %v",e)}}
func TestSymlinkEscape(t *testing.T){root,out:=t.TempDir(),t.TempDir();if e:=os.WriteFile(filepath.Join(out,"secret"),[]byte("secret"),0600);e!=nil{t.Fatal(e)};if e:=os.Symlink(out,filepath.Join(root,"escape"));e!=nil{t.Skip(e)};b,e:=newLocalBackend(root,true,true,true,true);if e!=nil{t.Fatal(e)};if _,e=b.Open(context.Background(),vfs.OpenOptions{Path:"escape/secret",Disposition:vfs.DispositionOpen});!errors.Is(e,os.ErrPermission){t.Fatalf("want symlink escape denied, got %v",e)}}
